export type TrendType = 'growing' | 'monthly' | 'yearly' | 'seasonal';

export interface TrendingKeyword {
  demographics?: TrendingKeywordDemographics;
  /**
   * Indicates whether the keyword has a prediction available for the next 90 days.<br /> This field is only applicable when `include_prediction` query parameter is set to `true`. <br /> By default, the value is `false` and no prediction data is included in the response.
   */
  has_prediction?: boolean;
  /**
   * The keyword that is trending.
   */
  keyword?: string;
  /**
   * The month-over-month percent change in search volume for this keyword.<br /> For example, a value of \"400\" would represent a 400% increase in searches in the last 30 days compared to the month prior.<br /> **Note**: growth rates are rounded, with a maximum of +/- 10000% change.  A value of 10001 indicates that this keyword experienced > 10000% month-over-month growth.
   */
  pct_growth_mom?: number;
  /**
   * The week-over-week percent change in search volume for this keyword.<br /> For example, a value of \"50\" would represent a 50% increase in searches in the last seven days compared to the week prior.<br /> **Note**: growth rates are rounded, with a maximum of +/- 10000% change.  A value of 10001 indicates that this keyword experienced > 10000% week-over-week growth.
   */
  pct_growth_wow?: number;
  /**
   * The year-over-year percent change in search volume for this keyword.<br /> For example, a value of \"-5\" would represent a 5% decrease in searches in the last 365 days compared to the month prior.<br /> **Note**: growth rates are rounded, with a maximum of +/- 10000% change.  A value of 10001 indicates that this keyword experienced > 10000% year-over-year growth.
   */
  pct_growth_yoy?: number;
  predicted_time_series?: PredictedTimeSeries;
  time_series?: TimeSeries;
}


/**
 * A mapping of demographic dimensions (e.g. \"gender\", \"age\") to their category distributions. <br /> For each dimension: <br />   - Key: The category (e.g., \"female\", \"18-24\"). <br />   - Value: The proportion of search volume (e.g., 0.12 for 12%). <br />     Values less than 0.05 are set to 0.04 for privacy. <br />     The sum for all categories in a dimension will approximately equal 1. <br />     Only applicable when `include_demographics` query parameter is set to `true`.
 */
export interface TrendingKeywordDemographics {
  age_distribution?: TrendingKeywordDemographicsAgeDistribution;
  gender_distribution?: TrendingKeywordDemographicsGenderDistribution;
}


/**
 * This represents a mapping from age bucket to distribution of search volume for a keyword. The sum of all values in this object should approximately be 1.
 */
export interface TrendingKeywordDemographicsAgeDistribution extends number {
  age_distribution?: TrendingKeywordDemographicsAgeDistributionAgeDistributionEnum;
}

/**
 * Enum for the age_distribution property.
 */
export type TrendingKeywordDemographicsAgeDistributionAgeDistributionEnum = '18-24' | '25-34' | '35-44' | '45-49' | '50-54' | '55-64' | '65+';


/**
 * This represents a mapping from gender to distribution of search volume for a keyword. The sum of all values in this object should approximately be 1.
 */
